func TestCalculateTokenUsage_GeminiIdentities(t *testing.T) {
	t.Parallel()

	data := []byte(`{
  "messages": [
    {"id": "1", "type": "user", "content": "hello"},
    {"id": "2", "type": "gemini", "content": "hi", "tokens": {"input": 100, "output": 20, "cached": 60, "thoughts": 15, "tool": 5, "total": 140}}
  ]
